5: pragma solidity ^0.8.20;
6: 
7: import "contracts/C.sol";
8: import "../ReentrancyGuard.sol";
9: 
10: /**
11:  * @author Brean
12:  * @title
13:  * @notice Allows beanstalk to recieve data from an L1, specifically to mint beans. see {BeanL2MigrationFacet} for more details.
14:  * The Facet implmentation may need to change depending on the L2 that the beanstalk DAO chooses to migrate to.
15:  **/
16: 
17: interface IL2Messenger {
18:     function xDomainMessageSender() external view returns (address);
19: }
20: 
21: contract BeanL1RecieverFacet is ReentrancyGuard {
22:     uint256 constant EXTERNAL_L1_BEANS = 0;
23: 
24:     address constant BRIDGE = address(0x4200000000000000000000000000000000000007);
25:     address constant L1BEANSTALK = address(0xC1E088fC1323b20BCBee9bd1B9fC9546db5624C5);
26: 
27:     /**
28:      * @notice migrates `amount` of Beans to L2,
29:      * issued to `reciever`.
30:      */
31:     function recieveL1Beans(address reciever, uint256 amount) external nonReentrant {
32:         // verify msg.sender is the cross-chain messenger address, and
33:         // the xDomainMessageSender is the L1 Beanstalk contract.
34:         require(
35:             msg.sender == address(BRIDGE) &&
36:                 IL2Messenger(BRIDGE).xDomainMessageSender() == L1BEANSTALK
37:         );
38:         s.sys.migration.migratedL1Beans += amount;
39:         require(
40:             EXTERNAL_L1_BEANS >= s.sys.migration.migratedL1Beans,
41:             "L2Migration: exceeds maximum migrated"
42:         );
43:         C.bean().mint(reciever, amount);
44:     }
45: }
